const raw = $input.first().json.output || $input.first().json.text || $input.first().json.content || '';
let parsed;
try {
  const cleaned = raw.replace(/```json?\n?/gi, '').replace(/```/g, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : cleaned);
} catch (e) {
  parsed = { risk_level: 'UNKNOWN', default_probability: null, key_signals: ['Parse error: ' + String(e.message)], recommendation: 'Manual review required.' };
}
return [{ json: parsed }];

var risk = $input.first().json;
var level = risk.risk_level || 'UNKNOWN';
var prob = ((risk.default_probability || 0) * 100).toFixed(0);
var signals = (risk.key_signals || []).join('
  * ');
var rec = risk.recommendation || 'Manual review required.';
var ds = risk.derived_signals || {};
var emailBody = 'CREDIT RISK ALERT — ' + level + ' RISK

' + 'Default Probability: ' + prob + '%

' + 'Key Risk Signals:
  * ' + signals + '

Recommendation: ' + rec + '

Derived Signals:
' + '  * Bill/Limit Ratio: ' + (ds.bill_to_limit_ratio !== undefined ? ds.bill_to_limit_ratio : 'N/A') + '
' + '  * Payment Coverage: ' + (ds.payment_coverage_ratio !== undefined ? ds.payment_coverage_ratio : 'N/A') + '
' + '  * Consecutive Delays: ' + (ds.consecutive_delays !== undefined ? ds.consecutive_delays : 'N/A') + ' month(s)
' + '  * Bill Trend: ' + (ds.bill_trend !== undefined ? ds.bill_trend : 'N/A') + ' NTD

' + '— Credit Assessment Agent | Africa Business School, UM6P 2026';
var whatsappText = 'CREDIT ALERT - ' + level + ' RISK%0AProbability: ' + prob + '%25%0A' + encodeURIComponent(rec);
return [{ json: Object.assign({}, risk, { emailBody: emailBody, whatsappText: whatsappText, alertLevel: level }) }];
